// Stage 1, final items (docs/ML.md): class weights, iterative imputation, nested tuning, lowess
// calibration and t-SNE. References: R glmnet (weights), R lowess, scikit-learn (class_weight,
// sample_weight, IterativeImputer with Ridge, t-SNE internals) and shap. Values in
// tests/fixtures/ml-reference.json, regenerated by ml-reference.R then ml-reference.py.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import * as M from '../web/lib/ml.mjs';
import * as S from '../web/lib/ml-shap.mjs';
import * as U from '../web/lib/ml-embed.mjs';
import { fitIterativeImputer, applyIterativeImputer } from '../web/lib/ml-impute.mjs';
import { trainReport } from '../web/lib/ml-pipeline.mjs';
import { syntheticBiomarker } from '../web/lib/ml-demo.mjs';

const R = JSON.parse(readFileSync(new URL('./fixtures/ml-reference.json', import.meta.url)));
const close = (a, b, tol, label = '') => { [].concat(a).forEach((v, i) => assert.ok(Math.abs(v - [].concat(b)[i]) <= tol, `${label}[${i}] ${v} vs ${[].concat(b)[i]}`)); };
const col = (m, k) => m.map(r => r[k]);

test('class-weighted elastic-net logistic matches R glmnet(weights = ...)', () => {
  const ref = R.binomial_weighted, fit = M.elasticNet(R.X, R.y, { family: 'binomial', alpha: 1, lambda: ref.lambda, weights: ref.weights });
  fit.path.forEach((s, k) => { close(s.beta, col(ref.beta, k), 5e-8, `beta λ${k}`); close(s.b0, ref.a0[k], 5e-9, `a0 λ${k}`); });
  close(M.elasticNet(R.X, R.y, { family: 'binomial', alpha: 1, nlambda: 5, weights: ref.weights }).path[0].lambda, ref.lambdaMax, 1e-12, 'λmax');
  close(M.balancedWeights(R.y), ref.weights, 1e-12, 'weights');
});

test('class-weighted CART, weighted boosting and weighted TreeSHAP match scikit-learn / shap', () => {
  const tr = R.X.slice(0, 150), y = R.y.slice(0, 150), te = R.X.slice(150);
  const tree = M.fitModel('tree', tr, y, { maxDepth: 3, minLeaf: 5, classWeight: 'balanced' });
  close(M.predictModel(tree, te).prob, R.weighted.tree_proba, 1e-12, 'tree');
  S.shapValues(tree, te.slice(0, 10)).values.forEach((row, i) => close(row, R.weighted.tree_shap[i], 1e-12, `shap ${i}`));
  const gbm = M.fitModel('gbm', tr, y, { nTrees: 30, learningRate: 0.1, maxDepth: 2, minLeaf: 10, subsample: 1, classWeight: 'balanced' });
  close(M.predictModel(gbm, te).prob, R.weighted.gbm_proba, 1e-10, 'gbm');
});

test('iterative imputation matches scikit-learn IterativeImputer(Ridge) on fit and on new rows', () => {
  const Xm = R.impute.X.map(r => r.map(v => (v == null ? NaN : v)));
  const { imputer, X } = fitIterativeImputer(Xm.slice(0, 150), { alpha: 1, maxIter: 10, tol: 1e-3 });
  assert.equal(imputer.iterations, R.impute.n_iter);
  X.forEach((row, i) => close(row, R.impute.fit[i], 1e-10, `fit ${i}`));
  applyIterativeImputer(imputer, Xm.slice(150)).forEach((row, i) => close(row, R.impute.transform[i], 1e-10, `transform ${i}`));
});

test('lowess matches R lowess (robust iterations, iter = 0, and a narrow span, with tied x)', () => {
  const L = R.lowess;
  close(M.lowess(L.x, L.y).y, L.fit3, 1e-12, 'iter 3');
  close(M.lowess(L.x, L.y, { iter: 0 }).y, L.fit0, 1e-12, 'iter 0');
  close(M.lowess(L.x, L.y, { f: 0.3, iter: 2 }).y, L.fit_f, 1e-12, 'f 0.3');
});

test('t-SNE joint probabilities, KL divergence and gradient match scikit-learn; a full run reaches its KL', () => {
  const T = R.tsne, Xs = R.X.slice(0, 120).map(r => r.slice(0, 6)), n = 120;
  const P = U.tsneJointProbabilities(Xs, T.perplexity);
  close(Array.from(P), T.P, 1e-9, 'P');
  const { kl, grad } = U.tsneKL(Float64Array.from(T.P), Float64Array.from(T.Y0.flat()), n);
  close(kl, T.kl, 1e-10, 'KL'); close(Array.from(grad), T.grad, 1e-10, 'grad');
  const run = U.tsne(Xs, { perplexity: T.perplexity, maxIter: T.max_iter, init: T.init });
  // Gradient descent amplifies last-bit differences: scikit-learn's own final KL from the same start
  // differs between float32 and float64 (stored as kl_final / kl_final_f64). Ours must fall in that band ± 5%.
  const lo = Math.min(T.kl_final, T.kl_final_f64) * 0.95, hi = Math.max(T.kl_final, T.kl_final_f64) * 1.05;
  assert.ok(run.kl >= lo && run.kl <= hi, `KL ${run.kl} outside scikit-learn's ${T.kl_final}–${T.kl_final_f64}`);
  assert.ok(U.trustworthiness(Xs, run.embedding, 5) > T.trust - 0.02, 'trustworthiness');
});

const demo = syntheticBiomarker(), H = demo.headers, rows = demo.rows;
const feats = ['age', 'ecog', 'arm', 'tmb', 'KRAS_mut', 'EGFR_mut', 'gene_01', 'gene_02', 'gene_05'].map(name => ({ name, kind: name === 'arm' ? 'categorical' : 'numeric' }));
const bin = { type: 'binary', column: 'response', positive: '1' }, surv = { type: 'survival', time: 'os_months', event: 'death' };

test('nested tuning picks from the documented grid inside every training fold and is reproducible', () => {
  const spec = { headers: H, rows, outcome: bin, features: feats, model: 'gbm', params: { tune: true, subsample: 1 }, folds: 3, seed: 8, importance: false };
  const a = M.trainEvaluate(spec), b = M.trainEvaluate(spec);
  assert.deepEqual(a.perFold.map(f => f.tuned), b.perFold.map(f => f.tuned));
  const g = M.TUNING_GRIDS.gbm();
  a.perFold.forEach(f => { assert.ok(g.maxDepth.includes(f.tuned.maxDepth) && g.learningRate.includes(f.tuned.learningRate) && g.nTrees.includes(f.tuned.nTrees)); });
  assert.equal(a.tuning.table.length, 18);
  assert.ok(a.summary.mean > 0.6, `CV AUC ${a.summary.mean}`);
  const r = M.trainEvaluate({ headers: H, rows, outcome: surv, features: feats, model: 'rsf', params: { tune: true, nTrees: 40 }, folds: 3, seed: 8, importance: false });
  assert.ok(r.tuning.best.minLeaf && r.summary.mean > 0.6);
});

test('iterative imputation runs inside cross-validation and is frozen with the exported model', () => {
  const r = trainReport({ headers: H, rows, outcome: bin, features: feats, model: 'logit_enet', imputation: 'iterative', folds: 3, seed: 4, importance: false });
  assert.equal(r.imputation, 'iterative');
  assert.ok(r.finalModel.preprocessor.imputer.sequence.length > 0);
  const applied = M.applyModel(JSON.parse(JSON.stringify(r.finalModel)), H, rows);
  assert.ok(Number.isFinite(applied.metrics.auc) && applied.predictions.every(p => Number.isFinite(p.prob)));
  assert.ok(r.calibrationSmooth.length > 10 && r.calibrationSmooth.every(([x, y]) => x >= 0 && x <= 1 && y >= 0 && y <= 1));
});

test('class weighting moves predicted risks towards 50% (hence the calibration warning)', () => {
  const plain = M.trainEvaluate({ headers: H, rows, outcome: bin, features: feats, model: 'logit_enet', folds: 3, seed: 3, importance: false });
  const weighted = M.trainEvaluate({ headers: H, rows, outcome: bin, features: feats, model: 'logit_enet', params: { classWeight: 'balanced' }, folds: 3, seed: 3, importance: false });
  const prev = plain.positives / plain.n;
  assert.ok(Math.abs(weighted.pooled.meanPredicted - 0.5) < Math.abs(plain.pooled.meanPredicted - 0.5) || Math.abs(prev - 0.5) < 0.02);
});
